(function () {
  'use strict';
  const chunkSet = {"title":"Book Genres","topic":"Reading Comprehension","questions":[{"id":"reading-comprehension-book-genres-q0151","version":3,"contentHash":"sha256:c1e4c6d13f432a6a6fe7f9207f70731d3c5ed884e368794109f02b3079ada66a","question":"Grade 5 Medium: Use the context to choose the best answer. A story with imaginary magic, invented creatures, and a quest is usually what genre?","choices":["biography","fantasy","realistic nonfiction","dictionary entry"],"correct":1,"studyAid":{"definition":"Fantasy is a genre of literature that uses magic, supernatural events, or mythical creatures as a primary part of the plot or setting.","example":"Harry Potter (wizards and magic), The Hobbit (dragons and imaginary races), Percy Jackson (Greek myths in modern times)","strategyClue":"Ask yourself if the story could happen in the real world. If the events rely on powers that don't exist in our world, look for the term associated with imagination.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: fantasy. This genre specifically features imaginary elements like magic and non-existent creatures, setting it apart from real-world accounts or references.","incorrect":[{"choice":"biography","category":"nonfiction literary genre","reason":"A biography is the true story of a real person's life. It does not include magic or made-up creatures."},"",{"choice":"realistic nonfiction","category":"factual writing genre","reason":"Realistic nonfiction focuses on facts and true events that happen in the real world, rather than imaginative quests or magic."},{"choice":"dictionary entry","category":"reference text type","reason":"A dictionary entry is meant to define a word, not to tell an imaginary story or describe a narrative quest."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":151,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0152","version":3,"contentHash":"sha256:ae841417bda486b4b344edc575aab414cc1c92373080199d57b08bc7052a1d0e","question":"Grade 5 Medium: Use the context to choose the best answer. A book that tells the true story of a person's life is what genre?","choices":["folktale","mystery","biography","poem only"],"correct":2,"studyAid":{"definition":"A biography is a nonfiction book that tells the true story of a real person's life. If a person writes their own life story, it is called an autobiography.","example":"A book about the life of Abraham Lincoln is a biography; a story about a dragon is fantasy; a story about a detective solving a crime is a mystery.","strategyClue":"Look at the prefix 'bio-' (which means life) and the suffix '-graphy' (which means writing). Think about which option describes a written account of a life versus a fictional story or a style of writing.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: biography. A biography is a specific genre of literature that documents the real events and experiences of a person's life written by another individual.","incorrect":[{"choice":"folktale","category":"fictional narrative genre","reason":"Folktales are stories passed down through generations, often involving magic or moral lessons, rather than true accounts of a real person's life."},{"choice":"mystery","category":"fictional suspense genre","reason":"A mystery is a story focused on solving a crime or a puzzle. While it can be exciting, it does not specifically mean it is a true story about someone's life."},"",{"choice":"poem only","category":"wrong format type","reason":"A poem is a format for writing that uses rhythm and imagery. A life story can be written as a book (a biography) regardless of whether it is written in poetry or prose."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":152,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0153","version":3,"contentHash":"sha256:888f135003519d13c7bfc74713577ef0604d3b4b5db8aacda591a46f86c0d13d","question":"Grade 5 Medium: Use the context to choose the best answer. A story passed down over time with a lesson and traditional characters is often a what?","choices":["lab report","index","news article","folktale"],"correct":3,"studyAid":{"definition":"A genre is a category of writing. A folktale is a specific genre of literature that focuses on cultural stories passed down orally.","example":"Folktale: 'The Tortoise and the Hare'; Non-fiction: 'History of the Moon'; Informational: 'How to Build a Birdhouse'.","strategyClue":"Think about whether the writing is meant to teach a lesson through a story or provide facts and data. Eliminate options that serve as reference tools or factual reports.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: folktale. A folktale is a narrative that has been handed down through generations and typically features traditional characters and a moral lesson.","incorrect":[{"choice":"lab report","category":"factual document type","reason":"A lab report is used to explain the steps and results of a scientific experiment, not to tell a story or share traditional lessons."},{"choice":"index","category":"reference book part","reason":"An index is a list found at the back of a book that helps you find specific topics; it is not a story or a type of narrative."},{"choice":"news article","category":"non-fiction writing","reason":"A news article is written to report current, factual events to the public, not to convey traditional folklore or cultural lessons."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":153,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0154","version":3,"contentHash":"sha256:f348b8dcb01619e63980c7d4d87de56f5e70886ce647d0a18e53afc58dd8e30b","question":"Grade 5 Medium: Use the context to choose the best answer. Which genre is most likely to include suspects and clues?","choices":["mystery","atlas","recipe","personal dictionary"],"correct":0,"studyAid":{"definition":"A mystery is a genre of literature where a protagonist attempts to solve a crime or puzzling event using evidence.","example":"Mystery: Detective solving a case. Recipe: How to bake a cake. Atlas: Maps of the world.","strategyClue":"Think about the main purpose of each book or story type. If the text aims to solve a secret, which label fits that action best?","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: mystery. A mystery story typically involves a crime or puzzle that needs to be solved by finding suspects and examining clues.","incorrect":["",{"choice":"atlas","category":"informational reference book","reason":"An atlas is a collection of maps and geographical information. It does not tell a story or contain suspects and clues."},{"choice":"recipe","category":"instructional text type","reason":"A recipe provides instructions for cooking a specific dish. It lists ingredients and steps, not fictional characters or investigative clues."},{"choice":"personal dictionary","category":"vocabulary reference tool","reason":"A personal dictionary is used to record and define new words you have learned. It is a reference tool, not a creative story genre."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":154,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0155","version":3,"contentHash":"sha256:c64b13b93235c4792808f78ed69b6527988d4a4ea22fbff10ce4a2b0bbb52352","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence is second-person point of view?","choices":["I stepped onto the trail.","You step onto the trail and lift your flashlight.","She stepped onto the trail.","They stepped onto the trail."],"correct":1,"studyAid":{"definition":"Second-person point of view talks directly to the reader by using the pronoun 'you', making the reader feel like they are inside the action.","example":"First-person: I ate lunch. Second-person: You ate lunch. Third-person: He ate lunch.","strategyClue":"Look at the subject of each sentence. Identify the pronoun and ask yourself, 'Am I talking about myself, someone else, or am I talking directly to the reader?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: You step onto the trail and lift your flashlight. Second-person point of view uses the pronouns 'you', 'your', and 'yours' to address the reader directly as if they are a character in the story.","incorrect":[{"choice":"I stepped onto the trail.","category":"first-person pronoun usage","reason":"This uses 'I', which is the first-person point of view. It describes the thoughts and actions of the narrator themselves, not the reader."},"",{"choice":"She stepped onto the trail.","category":"third-person pronoun usage","reason":"This uses 'she', which is the third-person point of view. It describes someone else from an outside perspective, not addressing the reader directly."},{"choice":"They stepped onto the trail.","category":"third-person pronoun usage","reason":"This uses 'they', which is the third-person point of view. It is used when talking about a group of other people, rather than the person reading the sentence."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":155,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0156","version":4,"contentHash":"sha256:9b270940e2d5916992c95101e48c6684a016566d6cf36214a9a179ac172edac2","question":"Grade 5 Medium: Use the context to choose the best answer. Which detail supports a tense mood?","choices":["The kitten slept in sun.","The picnic blanket was bright yellow.","The clock ticked loudly as footsteps stopped outside the door.","The song ended cheerfully."],"correct":2,"studyAid":{"definition":"Mood is the feeling or atmosphere a writer creates for the reader through word choices and descriptions. A tense mood often involves suspense, quiet moments, or the feeling that something bad might happen.","example":"Tense: 'The shadows stretched long across the hallway.' Peaceful: 'The sun warmed the grass.'","strategyClue":"Look for words that suggest anticipation, mystery, or danger versus words that suggest comfort, happiness, or safety.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The clock ticked loudly as footsteps stopped outside the door. This sentence creates a tense mood because the loud ticking and sudden silence of the footsteps create suspense and anticipation of something unexpected.","incorrect":[{"choice":"The kitten slept in sun.","category":"peaceful imagery","reason":"A kitten sleeping is a calm and cozy image, which conveys a sense of safety and relaxation rather than tension."},{"choice":"The picnic blanket was bright yellow.","category":"cheerful description","reason":"Bright colors like yellow are usually associated with happiness and outdoor fun, not a tense or nervous mood."},"",{"choice":"The song ended cheerfully.","category":"positive tone","reason":"The word 'cheerfully' directly describes a happy, upbeat emotion, which is the opposite of the suspense and worry found in a tense scene."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":156,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0157","version":3,"contentHash":"sha256:c67f48ebd9c8a54a0b3a1a7d5b0a6481ac8f2b3e41204ca543410b80dc09a8f3","question":"Grade 5 Medium: Use the context to choose the best answer. Which text is most likely historical fiction?","choices":["a weather chart","a dictionary page","a present-day lunch menu","a made-up story set during the building of the first railroads"],"correct":3,"studyAid":{"definition":"Historical fiction is a story that mixes imaginary characters or events with a real time period or major event from history.","example":"A story about a girl living through the Great Depression; A tale about a knight in the Middle Ages.","strategyClue":"Look for a combination of two things: a made-up narrative and a setting that occurred in the past.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: a made-up story set during the building of the first railroads. Historical fiction is a genre where a fictional story takes place in a real time and setting from the past.","incorrect":[{"choice":"a weather chart","category":"non-fiction informational text","reason":"A weather chart provides factual, current data about the climate; it does not tell a story or feature fictional characters."},{"choice":"a dictionary page","category":"reference resource","reason":"A dictionary is a reference book used to define words. It contains lists, not a narrative plot set in a historical time period."},{"choice":"a present-day lunch menu","category":"non-fiction document","reason":"A lunch menu is a practical document for the current day; it lacks the narrative elements and historical setting required for historical fiction."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":157,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0158","version":3,"contentHash":"sha256:aba321afc32360eb8bfdb3219e8c61c745c917f5f35b413b9ad77768050c9961","question":"Grade 5 Medium: Use the context to choose the best answer. A story with imaginary magic, invented creatures, and a quest is usually what genre?","choices":["fantasy","biography","realistic nonfiction","dictionary entry"],"correct":0,"studyAid":{"definition":"Fantasy is a genre of literature that uses magic or other supernatural elements as a primary plot, theme, or setting.","example":"Correct: 'The hero rode a dragon into the clouds.' Incorrect: 'The hero drove a bus to the grocery store.'","strategyClue":"Ask yourself if the elements described could exist in the real world or if they require magic to happen. If the elements are impossible in real life, look for the term that describes imaginative or make-believe stories.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: fantasy. This genre is defined by elements that do not exist in the real world, such as magic, mythical creatures, and epic quests.","incorrect":["",{"choice":"biography","category":"factual genre error","reason":"A biography is a true account of a real person's life, whereas the question describes imaginary elements that are not based on reality."},{"choice":"realistic nonfiction","category":"nonfiction genre error","reason":"Nonfiction focuses on facts and true information. Since the question asks about invented creatures and magic, it cannot be nonfiction."},{"choice":"dictionary entry","category":"text structure error","reason":"A dictionary entry is a list of word definitions and pronunciations, not a type of creative storytelling genre."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":158,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0159","version":3,"contentHash":"sha256:faee7c082984b014c9d575279956280c729977f0fc684f9b3bad37e0869455ec","question":"Grade 5 Medium: Use the context to choose the best answer. A book that tells the true story of a person's life is what genre?","choices":["mystery","biography","folktale","poem only"],"correct":1,"studyAid":{"definition":"A biography is a nonfiction book written about a real person's life, while an autobiography is written by the person themselves.","example":"A book about the life of Abraham Lincoln is a biography. A book about the life of Albert Einstein is a biography.","strategyClue":"Look for keywords like 'true story' and 'person's life' to identify nonfiction categories, and eliminate genres that focus on imagination or solving crimes.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: biography. A biography is a nonfiction text that provides a factual account of someone's life, written by another person.","incorrect":[{"choice":"mystery","category":"incorrect story genre","reason":"A mystery is a story centered on solving a crime or secret, not a factual account of a person's life history."},"",{"choice":"folktale","category":"incorrect story genre","reason":"Folktales are traditional stories passed down through generations, usually involving legends or magic, rather than documented historical facts about a person."},{"choice":"poem only","category":"incorrect writing format","reason":"A poem is a style of writing using lines and rhythm, but a life story written as a prose narrative is specifically defined as a biography."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":159,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0160","version":3,"contentHash":"sha256:f94563a03b459e5c3dd5d919f0bc2601f8ce27fd47663c336aec51f07f09d8e7","question":"Grade 5 Medium: Use the context to choose the best answer. A story passed down over time with a lesson and traditional characters is often a what?","choices":["news article","index","folktale","lab report"],"correct":2,"studyAid":{"definition":"A folktale is a story from oral tradition that often features legendary characters and teaches a specific moral or lesson.","example":"The Tortoise and the Hare, Anansi the Spider stories, Johnny Appleseed","strategyClue":"Think about the purpose of the writing. Does it explain a recent event, record data, or tell a timeless story to teach a lesson?","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: folktale. A folktale is a traditional story passed down through generations that often includes a lesson and culturally significant characters.","incorrect":[{"choice":"news article","category":"non-fiction text type","reason":"A news article reports on recent, factual events rather than sharing a traditional, handed-down story with a moral lesson."},{"choice":"index","category":"non-fiction text feature","reason":"An index is a list found at the back of a book to help you find specific information; it is a reference tool, not a narrative story."},"",{"choice":"lab report","category":"scientific writing style","reason":"A lab report is used to explain the steps and results of a science experiment, not to entertain or teach a cultural lesson."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":160,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0161","version":4,"contentHash":"sha256:546a2a96c351ea50f0d07e45e6f841299a7d3ed8fdcbbff752335c0d38466ede","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence is written from first-person point of view?","choices":["Maya found a map.","She tucked the map away.","They saw the map.","I tucked the map into my backpack."],"correct":3,"studyAid":{"definition":"First-person point of view means the narrator is a character inside the story who tells you what they are thinking or doing.","example":"First-person: I walked to the park. Third-person: He walked to the park.","strategyClue":"Look at the subject of each sentence. Ask yourself: 'Is the narrator using pronouns that refer to themselves as the main actor, or are they talking about someone else?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: I tucked the map into my backpack. This sentence uses the pronoun 'I', which indicates the narrator is talking about their own experiences, identifying it as the first-person point of view.","incorrect":[{"choice":"Maya found a map.","category":"third-person point of view","reason":"This sentence uses a character's name to describe the action. When a story talks about a person by name, it is written in the third person."},{"choice":"She tucked the map away.","category":"third-person point of view","reason":"The pronoun 'She' is used here. Third-person pronouns like 'he', 'she', or 'they' tell us the narrator is observing the characters from the outside."},{"choice":"They saw the map.","category":"third-person point of view","reason":"The word 'They' is a third-person pronoun. First-person sentences must focus on the narrator speaking for themselves, not on a group of other people."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":161,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0162","version":4,"contentHash":"sha256:426c4bcd53d356ead415d84fff899eacc2f8a4e799fd34cdc3dfe93100d26980","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence is third-person limited?","choices":["Eli wondered whether anyone else heard the sound.","I heard the sound.","Everyone's secret thoughts were explained.","Listen to the sound."],"correct":0,"studyAid":{"definition":"Third-person limited perspective uses 'he', 'she', or a character's name, while only revealing the thoughts and feelings of one single character.","example":"Limited: Sarah felt nervous about the test. / Omniscient: Sarah felt nervous, but Mark felt calm and ready.","strategyClue":"Ask yourself: 'Can I see inside the head of more than one person, or is the narrator stuck inside just one character's perspective?' Look for pronouns and mental verbs like 'wondered' or 'thought'.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Eli wondered whether anyone else heard the sound. In third-person limited, the narrator focuses on the thoughts and feelings of only one specific character (in this case, Eli).","incorrect":["",{"choice":"I heard the sound.","category":"first-person perspective","reason":"This sentence uses 'I', which means the narrator is the character experiencing the action. This is first-person, not third-person."},{"choice":"Everyone's secret thoughts were explained.","category":"third-person omniscient","reason":"By showing the thoughts of 'everyone', the narrator has god-like knowledge of all characters. This is third-person omniscient, not limited."},{"choice":"Listen to the sound.","category":"second-person imperative","reason":"This is a command directed at the reader (an implied 'you'). It does not focus on a character's internal experience from a distance."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":162,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0163","version":3,"contentHash":"sha256:0d791d229b6cc2a93e40a6ce1940d42248f86666422483698db6bbf2cb612817","question":"Grade 5 Medium: Use the context to choose the best answer. Which clue suggests an unreliable narrator?","choices":["The narrator uses complete sentences.","The narrator's claim is contradicted by clear events in the story.","The narrator names the setting.","The narrator appears in chapter one."],"correct":1,"studyAid":{"definition":"An unreliable narrator is a storyteller who cannot be fully trusted because their perspective is biased, mistaken, or intentionally misleading.","example":"A character says they are 'totally calm' while the text describes their hands shaking and their voice cracking.","strategyClue":"Look for a disconnect between what the character is thinking or saying versus what is actually happening in the scene around them.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The narrator's claim is contradicted by clear events in the story. An unreliable narrator is one whose credibility is compromised, often because their version of events does not match the facts shown by the author.","incorrect":[{"choice":"The narrator uses complete sentences.","category":"writing style choice","reason":"Using complete sentences is a standard writing style and does not tell us anything about whether the narrator is telling the truth."},"",{"choice":"The narrator names the setting.","category":"story detail usage","reason":"Naming a setting is a basic storytelling task. Providing factual information like this actually makes a narrator seem more reliable, not less."},{"choice":"The narrator appears in chapter one.","category":"character introduction","reason":"Introducing a character early in the story is a common plot device and has nothing to do with whether that character is being honest or accurate."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":163,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0164","version":4,"contentHash":"sha256:8ed970d2e5b893214078e55b3cfd650a9bbb59dc1facc59b4f84b5d4831c6efa","question":"Grade 5 Medium: Use the context to choose the best answer. Which word choice creates a worried tone?","choices":["playful","delighted","uneasy","carefree"],"correct":2,"studyAid":{"definition":"Tone is the emotion or attitude behind the words a writer chooses. Selecting specific adjectives can change the mood from happy to sad, excited to nervous, or calm to worried.","example":"Worried: 'He felt uneasy about the storm.' vs. Relaxed: 'He felt carefree during the sunny day.'","strategyClue":"Replace the word with each option and ask yourself, 'Does this character feel happy, relaxed, or worried?' Pick the word that matches the negative or nervous feeling of being worried.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: uneasy. The word 'uneasy' describes a feeling of being anxious or uncomfortable, which creates a worried tone in a sentence.","incorrect":[{"choice":"playful","category":"wrong emotional tone","reason":"Choosing 'playful' suggests someone is having fun or acting in a lighthearted way, which is the opposite of a worried tone."},{"choice":"delighted","category":"positive emotion word","reason":"'Delighted' expresses great happiness or joy, which does not match a context requiring a worried or concerned tone."},"",{"choice":"carefree","category":"relaxed emotional tone","reason":"A 'carefree' person has no worries at all. Using this word would create a relaxed or happy tone, not a worried one."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":164,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0165","version":4,"contentHash":"sha256:b6890344430905712dbe759f702462ca7a64f670a0a936c3b937d167917979ff","question":"Grade 5 Medium: Use the context to choose the best answer. Which detail creates a gloomy mood?","choices":["warm cookies cooled on the counter.","sunlit flags snapped in a bright breeze.","children cheered at the finish line.","gray rain slid down the empty windows."],"correct":3,"studyAid":{"definition":"Mood is the feeling or atmosphere a writer creates for the reader through specific word choices and details.","example":"Gloomy: dark shadows, silent halls. Cheerful: bright sunshine, laughing friends.","strategyClue":"Look at the adjectives and nouns in each choice and ask yourself: 'Does this image make me feel happy, sad, or relaxed?' Pick the option that evokes feelings of sadness or dreariness.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: gray rain slid down the empty windows. This detail creates a gloomy mood because 'gray,' 'rain,' and 'empty' are all words commonly associated with sadness, loneliness, and dreary weather.","incorrect":[{"choice":"warm cookies cooled on the counter.","category":"positive imagery","reason":"This sentence suggests comfort and home, which creates a cozy or inviting mood, not a gloomy one."},{"choice":"sunlit flags snapped in a bright breeze.","category":"energetic imagery","reason":"The words 'sunlit' and 'bright' describe a cheerful and active scene, which is the opposite of a gloomy mood."},{"choice":"children cheered at the finish line.","category":"joyful imagery","reason":"The act of cheering is associated with excitement and happiness, which creates a celebratory mood rather than a gloomy one."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":165,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0166","version":3,"contentHash":"sha256:0a79b9552c0d0e473f41b8509871db091ad11bc803539b98362b95228ecb2e77","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. A story with imaginary magic, invented creatures, and a quest is usually what genre?","choices":["fantasy","biography","realistic nonfiction","dictionary entry"],"correct":0,"studyAid":{"definition":"The fantasy genre includes stories that feature impossible events, magical powers, or creatures that do not exist in our world.","example":"Harry Potter, The Hobbit, The Chronicles of Narnia","strategyClue":"Ask yourself if the elements in the story could exist in the real world. If the story requires magic or impossible beings, look for the term that describes imaginative fiction.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: fantasy. This genre is defined by elements that cannot happen in the real world, such as magic, mythical creatures, and epic quests.","incorrect":["",{"choice":"biography","category":"nonfiction literary genre","reason":"A biography is a true account of a real person's life, not a story about made-up creatures or magic."},{"choice":"realistic nonfiction","category":"factual writing style","reason":"Nonfiction describes real events or facts, so it would not include imaginary magic or invented creatures."},{"choice":"dictionary entry","category":"reference text type","reason":"A dictionary entry is a tool used to define words, not a creative story about characters going on a quest."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":166,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0167","version":3,"contentHash":"sha256:07a6801181149c35db7654197144d5143844918a7620ab43561648c872840437","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. A book that tells the true story of a person's life is what genre?","choices":["mystery","biography","folktale","poem only"],"correct":1,"studyAid":{"definition":"A biography is a form of nonfiction literature that tells the true story of a real person's life, written by another author.","example":"A book about George Washington's childhood, a story about Malala Yousafzai's life, an account of an inventor's daily work.","strategyClue":"Look at the prefix 'bio-' (meaning life) and the suffix '-graphy' (meaning writing). When you see these together, ask yourself if the book describes a sequence of real life events.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: biography. A biography is a specific type of nonfiction book written by someone else that narrates the true events and history of a real person's life.","incorrect":[{"choice":"mystery","category":"incorrect literary genre","reason":"A mystery is a story focused on solving a crime or a puzzling event. While mysteries can be true, the term 'biography' specifically defines a book about a person's life history."},"",{"choice":"folktale","category":"incorrect literary genre","reason":"A folktale is a story passed down through generations, often involving legends or myths. Folktales are usually fictional, whereas the genre for a true story about a person's life is a biography."},{"choice":"poem only","category":"incorrect writing style","reason":"While a life story can be written in poetry, 'poem only' is a format, not a genre. A book detailing a real person's life is categorized as a biography."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":167,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0168","version":3,"contentHash":"sha256:1b1db8156fc81a96fdb87deba27b3f56c07f8abdca8c172f1147ccaa21ac5ee3","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. A story passed down over time with a lesson and traditional characters is often a what?","choices":["news article","index","folktale","lab report"],"correct":2,"studyAid":{"definition":"A folktale is a traditional story that has been shared orally through generations and often teaches a cultural value or lesson.","example":"The Tortoise and the Hare (Aesop's Fable), The Three Little Pigs, Paul Bunyan","strategyClue":"Ask yourself if the writing is meant to teach a lesson through characters and a plot, or if it is intended to provide scientific data, alphabetical reference, or breaking news information.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: folktale. A folktale is a story passed down through generations, often featuring traditional characters, magic, or animals, and it typically conveys a moral or cultural lesson.","incorrect":[{"choice":"news article","category":"factual report writing","reason":"A news article is a piece of factual writing about current events that happened recently, not an old story passed down through time."},{"choice":"index","category":"informational text feature","reason":"An index is an alphabetical list at the back of a book used to find specific topics; it is a reference tool, not a narrative story."},"",{"choice":"lab report","category":"scientific writing style","reason":"A lab report is a technical document that describes a scientific experiment and its results, not a creative narrative with lessons or traditional characters."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":168,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0169","version":3,"contentHash":"sha256:3f1471f7ca355543ba5635b84ae998f20081bf3112d35bc17729f5bbcdafbc1c","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which genre is most likely to include suspects and clues?","choices":["personal dictionary","atlas","recipe","mystery"],"correct":3,"studyAid":{"definition":"A genre is a specific type or category of literature, and a 'mystery' is a genre focused on solving a puzzle or crime.","example":"Mystery: Nancy Drew books. Non-fiction: A book about how to bake a cake. Reference: A map of the world.","strategyClue":"Think about the purpose of each item: does it tell a story with a plot, or is it used to look up facts and follow directions?","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: mystery. A mystery story is defined by a puzzle, secret, or crime that characters must solve by gathering clues and identifying suspects.","incorrect":[{"choice":"personal dictionary","category":"informational text type","reason":"A personal dictionary is a reference tool for spelling and defining words, not a narrative genre that features plots or character conflicts."},{"choice":"atlas","category":"reference book category","reason":"An atlas is a collection of maps used for geographic research. It does not contain stories about suspects or criminal investigations."},{"choice":"recipe","category":"procedural text type","reason":"A recipe provides instructions for cooking a specific dish; it is a set of steps, not a fictional story involving mystery elements."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":169,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0170","version":3,"contentHash":"sha256:91d5a33a9378b2f3afe13dd5b2178efffd167cfcfa0941615e81f2d6ff3090fc","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence is second-person point of view?","choices":["You step onto the trail and lift your flashlight.","I stepped onto the trail.","She stepped onto the trail.","They stepped onto the trail."],"correct":0,"studyAid":{"definition":"Second-person point of view uses the pronoun 'you' to speak directly to the reader, drawing them into the action of the story.","example":"First-person: I run home. Second-person: You run home. Third-person: He runs home.","strategyClue":"Look for the specific pronoun that addresses the reader; scan each sentence for the word that names the person performing the action.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: You step onto the trail and lift your flashlight. Second-person point of view addresses the reader directly by using the pronoun 'you', making it feel as if the reader is part of the story.","incorrect":["",{"choice":"I stepped onto the trail.","category":"first-person point of view","reason":"This uses the pronoun 'I', which means the narrator is telling their own story. This is known as first-person, not second-person."},{"choice":"She stepped onto the trail.","category":"third-person point of view","reason":"This uses the pronoun 'she', which describes someone else from the outside. This is third-person point of view."},{"choice":"They stepped onto the trail.","category":"third-person point of view","reason":"This uses the pronoun 'they', referring to a group of people from the outside. Third-person narratives describe others, while second-person includes 'you'."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":170,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0171","version":4,"contentHash":"sha256:306e093b9ce77e74ea4f0d8242049e3685a51686b88e7f7f33f9101e0efaddfa","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which detail supports a tense mood?","choices":["The picnic blanket was bright yellow.","The clock ticked loudly as footsteps stopped outside the door.","The kitten slept in sun.","The song ended cheerfully."],"correct":1,"studyAid":{"definition":"Mood is the feeling a reader gets from a story, created by word choices, imagery, and the pace of the action.","example":"Tense: Shadows stretched across the empty hallway. Happy: Bubbles danced in the sunlight.","strategyClue":"Look for words that describe sounds or movements that make the reader feel worried or curious about what happens next, rather than words describing light or pleasant activities.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The clock ticked loudly as footsteps stopped outside the door. This sentence creates tension because the sensory details—the loud ticking and the abrupt silence of footsteps—suggest anticipation or danger, keeping the reader on edge.","incorrect":[{"choice":"The picnic blanket was bright yellow.","category":"cheerful sensory detail","reason":"Bright colors like yellow often suggest warmth and happiness, which creates a bright or peaceful mood rather than a tense one."},"",{"choice":"The kitten slept in sun.","category":"peaceful imagery","reason":"A sleeping kitten is a gentle, calming image. This choice creates a cozy or relaxed mood, not a feeling of suspense."},{"choice":"The song ended cheerfully.","category":"explicit happy tone","reason":"The word 'cheerfully' directly describes a happy mood, which is the opposite of the suspense or anxiety found in a tense scene."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":171,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0172","version":3,"contentHash":"sha256:dd8ada79f4197e1c7a9286e9642b49f54c2de26ff21a3a95ad7bdfcb49b883a7","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which text is most likely historical fiction?","choices":["a present-day lunch menu","a dictionary page","a made-up story set during the building of the first railroads","a weather chart"],"correct":2,"studyAid":{"definition":"Historical fiction combines real historical settings with invented characters and plot points to help readers imagine what life was like in the past.","example":"A book about a girl living through the Great Depression, a story about a boy who meets a famous explorer.","strategyClue":"Ask yourself: 'Does this tell a story?' and 'Does this take place in a real time period from long ago?' Only the historical fiction option will have both.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: a made-up story set during the building of the first railroads. Historical fiction is a genre where the characters and plot are invented, but they are placed in a realistic setting from the past.","incorrect":[{"choice":"a present-day lunch menu","category":"non-fiction informational text","reason":"A lunch menu is a list of current food options, not a story, and it focuses on the present rather than the past."},{"choice":"a dictionary page","category":"reference material","reason":"A dictionary is a tool used for defining words. It provides factual information rather than telling a story about the past."},"",{"choice":"a weather chart","category":"scientific data display","reason":"A weather chart tracks climate information or forecasts. It is a factual document, not a fictional narrative."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":172,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0173","version":3,"contentHash":"sha256:b0331440ffcf18504964f1e8e564951a06e087ff094cb2fd8b4b5a97f0d22195","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. A story with imaginary magic, invented creatures, and a quest is usually what genre?","choices":["dictionary entry","biography","realistic nonfiction","fantasy"],"correct":3,"studyAid":{"definition":"Fantasy is a genre of fiction that includes magical elements, imaginary worlds, or supernatural beings that do not exist in the real world.","example":"Fantasy: A wizard searching for a dragon's egg. Nonfiction: A book about how bees make honey.","strategyClue":"Ask yourself if the story elements could possibly exist in the real world. If the answer is no because of magic or mythical creatures, it belongs to this genre.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: fantasy. This genre is defined by elements that cannot happen in the real world, such as magic and creatures that do not exist in nature.","incorrect":[{"choice":"dictionary entry","category":"incorrect text type","reason":"A dictionary entry is a reference tool used to define words, not a creative story genre featuring magic and quests."},{"choice":"biography","category":"nonfiction genre error","reason":"A biography is a true story about a real person's life; it does not contain invented creatures or imaginary magic."},{"choice":"realistic nonfiction","category":"factual genre error","reason":"Realistic nonfiction focuses on facts and true events. Imaginary magic and invented creatures belong to fiction, not nonfiction."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":173,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0174","version":3,"contentHash":"sha256:ef5ed4c8c2ab50f762646791765b8c8a2e9b005be3b5ed6dc4c485eb46b2bcd5","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. A book that tells the true story of a person's life is what genre?","choices":["biography","mystery","folktale","poem only"],"correct":0,"studyAid":{"definition":"A biography is a nonfiction book written to tell the true story of a real person's life.","example":"A book about the life of George Washington is a biography; a book about a fictional detective is a mystery.","strategyClue":"Break the word down: 'bio' comes from the Greek word for life, and 'graph' refers to writing. Look for these roots to identify which genre focuses on recording a person's life story.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: biography. A biography is a nonfiction text written by someone else that documents the actual life events and experiences of a specific person.","incorrect":["",{"choice":"mystery","category":"genre identification error","reason":"A mystery is a story centered around a crime or puzzle that needs to be solved, rather than a record of a real person's life history."},{"choice":"folktale","category":"genre identification error","reason":"A folktale is a story passed down through generations, often featuring made-up characters and lessons, not a factual account of a real person's life."},{"choice":"poem only","category":"literary format confusion","reason":"While a biography can be written in many formats, 'poem only' is too restrictive and does not define the genre of a book about a person's life."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":174,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0175","version":3,"contentHash":"sha256:eaff10195eee4ed1b743fa8bf8050470f7b7d19c21e6f9c493f3ff09f00d8838","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. A story passed down over time with a lesson and traditional characters is often a what?","choices":["index","folktale","news article","lab report"],"correct":1,"studyAid":{"definition":"A folktale is a traditional story that has been shared orally for many years and often teaches a cultural lesson.","example":"The Tortoise and the Hare, Anansi the Spider stories, Paul Bunyan tall tales","strategyClue":"Think about the purpose of the writing: Is it explaining a scientific process, listing information, reporting current news, or telling a fictional story with a moral?","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: folktale. A folktale is a story passed down through generations that contains cultural traditions, life lessons, and often features mythical or anthropomorphized characters.","incorrect":[{"choice":"index","category":"informational text structure","reason":"An index is an alphabetical list of topics found at the back of a book, not a type of narrative story."},"",{"choice":"news article","category":"non-fiction writing","reason":"A news article reports on current, factual events happening in the real world, rather than traditional, fictionalized stories with morals."},{"choice":"lab report","category":"scientific writing style","reason":"A lab report is used to explain the steps and results of a scientific experiment; it does not contain the traditional characters or moral lessons found in stories."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":175,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0176","version":4,"contentHash":"sha256:7bc18f99300c22fb8d13b1013d8455220754c17337b5aadf4b35c9748dbdf93e","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence is written from first-person point of view?","choices":["They saw the map.","She tucked the map away.","I tucked the map into my backpack.","Maya found a map."],"correct":2,"studyAid":{"definition":"First-person point of view is when the narrator is a character in the story, using pronouns like 'I,' 'me,' 'my,' or 'we.'","example":"I walked home (First-person). She walked home (Third-person). We cheered for the team (First-person).","strategyClue":"Look for pronouns that identify the speaker as the person telling the story. Ask yourself: Is the narrator acting as a character within the sentence?","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: I tucked the map into my backpack. This sentence uses the pronoun 'I', which indicates the narrator is participating in the events of the story, characteristic of the first-person point of view.","incorrect":[{"choice":"They saw the map.","category":"third-person perspective","reason":"This uses 'they,' which refers to characters outside of the narrator. This is third-person point of view because the narrator is observing others."},{"choice":"She tucked the map away.","category":"third-person perspective","reason":"By using the pronoun 'she,' the narrator is describing someone else's actions rather than participating as 'I' or 'we.' This is third-person."},"",{"choice":"Maya found a map.","category":"third-person perspective","reason":"Using a proper name like 'Maya' shows that the narrator is observing the character from the outside. First-person would require the narrator to be the one taking action."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":176,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0177","version":4,"contentHash":"sha256:ad1b6b476a0c6f06463839abe5cdfdf225838ae9ae18ac15ba971ee0e6a3c6ce","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence is third-person limited?","choices":["Listen to the sound.","I heard the sound.","Everyone's secret thoughts were explained.","Eli wondered whether anyone else heard the sound."],"correct":3,"studyAid":{"definition":"Third-person limited point of view tells the story from the perspective of only one character, using pronouns like he, she, or they to share that person's thoughts.","example":"Limited: Sarah felt nervous. Omniscient: Sarah felt nervous, and she knew the teacher was frustrated, too.","strategyClue":"Check if the sentence describes the inner thoughts of one character or many, and look for pronouns like 'he' or 'she' instead of 'I' or 'we'.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Eli wondered whether anyone else heard the sound. This sentence is third-person limited because it focuses on the internal thoughts and feelings of one character (Eli) using third-person pronouns.","incorrect":[{"choice":"Listen to the sound.","category":"imperative sentence type","reason":"This is an imperative sentence (a command), not a narrative sentence. It lacks a subject and does not provide a character's perspective."},{"choice":"I heard the sound.","category":"first-person point of view","reason":"This uses 'I', which is the first-person perspective. Third-person limited must use pronouns like 'he', 'she', or 'they' to describe a single character's experience."},{"choice":"Everyone's secret thoughts were explained.","category":"third-person omniscient","reason":"This is third-person omniscient because it describes the thoughts of 'everyone' at once. Third-person limited is restricted to only one character's point of view."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":177,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0178","version":3,"contentHash":"sha256:ee2eac23fe2d2418dc0abc564571b9f76d26fb8a16d2d17fb18f292079d58b96","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which clue suggests an unreliable narrator?","choices":["The narrator's claim is contradicted by clear events in the story.","The narrator uses complete sentences.","The narrator names the setting.","The narrator appears in chapter one."],"correct":0,"studyAid":{"definition":"An unreliable narrator is a storyteller who cannot be fully trusted because they might be biased, confused, or intentionally lying to the reader.","example":"A narrator says they are brave, but describes themselves running away from a harmless shadow; a narrator claims to be alone, but the story reveals others are watching them.","strategyClue":"Compare what the character says happened with what the author shows happening on the page; look for gaps between the narrator's thoughts and the actual evidence provided in the plot.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The narrator's claim is contradicted by clear events in the story. An unreliable narrator is one whose credibility is compromised, often because their perspective of events does not match the objective reality shown in the text.","incorrect":["",{"choice":"The narrator uses complete sentences.","category":"style and grammar","reason":"Using proper grammar or complete sentences does not affect a narrator's honesty or reliability; it just describes their writing style."},{"choice":"The narrator names the setting.","category":"narrative exposition","reason":"Naming the setting is a standard way to ground the reader in the story's world and does not indicate that the narrator is hiding or misrepresenting the truth."},{"choice":"The narrator appears in chapter one.","category":"plot structure","reason":"Introducing a character early in the story is a normal narrative technique; being present at the start of the book says nothing about their truthfulness."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":178,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0179","version":4,"contentHash":"sha256:94a7779261c6077d2780303ccaba6526ba099544ff667d5dfcf6b61631fb6f93","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which word choice creates a worried tone?","choices":["delighted","uneasy","playful","carefree"],"correct":1,"studyAid":{"definition":"Tone is the attitude or feeling an author creates through specific word choices, known as diction.","example":"Worried tone: 'The dark clouds gathered.' Happy tone: 'The warm sun shone brightly.'","strategyClue":"Define each option based on the emotion it describes, then determine which of those emotions fits the feeling of being nervous or troubled.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: uneasy. The word 'uneasy' directly conveys feelings of anxiety, restlessness, or nervousness, which establishes a worried tone.","incorrect":[{"choice":"delighted","category":"positive emotion","reason":"This word describes extreme happiness, which is the opposite of being worried or anxious."},"",{"choice":"playful","category":"lighthearted mood","reason":"This word suggests fun and silliness, creating a cheerful atmosphere rather than a worried one."},{"choice":"carefree","category":"relaxed attitude","reason":"This word implies a lack of worry or concern, making it the wrong choice for establishing a tense or nervous tone."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":179,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0180","version":4,"contentHash":"sha256:4eb4eb8eb3f0bd5d28c93c028bf94a1836c9ab74ec04ee7bfe4413812f795ea8","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which detail creates a gloomy mood?","choices":["children cheered at the finish line.","sunlit flags snapped in a bright breeze.","gray rain slid down the empty windows.","warm cookies cooled on the counter."],"correct":2,"studyAid":{"definition":"Mood is the feeling or atmosphere created by an author's choice of words and descriptive details.","example":"Gloomy: dark shadows, heavy fog. Joyful: laughing, bright sunshine. Tense: ticking clock, quiet whispers.","strategyClue":"Focus on the adjectives and sensory words in each sentence; ask yourself if the image makes you feel cold and sad, or warm and happy.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: gray rain slid down the empty windows. The words 'gray', 'rain', and 'empty' contribute to a somber, lonely, or melancholy atmosphere, which is the definition of a gloomy mood.","incorrect":[{"choice":"children cheered at the finish line.","category":"joyful action","reason":"Cheering is an expression of excitement and happiness, which creates an energetic or celebratory mood rather than a gloomy one."},{"choice":"sunlit flags snapped in a bright breeze.","category":"bright imagery","reason":"Words like 'sunlit' and 'bright' suggest warmth and happiness, which are the opposite of the dark or dreary feelings found in a gloomy mood."},"",{"choice":"warm cookies cooled on the counter.","category":"cozy association","reason":"The mention of warm food often evokes feelings of comfort and home, creating a cozy and pleasant mood instead of a gloomy one."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["genre","literary reading"],"standards":["RL.2-6.5"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sequence":180,"skillIds":[],"standardIds":["RL.2-6.5"]}},{"id":"reading-comprehension-book-genres-q0181","version":3,"contentHash":"sha256:0395ca4e3e968c4c24c568f186603e94ff7a2865f97062796b54df092489592b","question":"Read the passage. Learning to read is important for everyone. Reading is important if you want to learn how to put something together. Some people read f or fun. But everyone needs to read if they want to be successful in getting a job. This passage is an example of what kind of writing?","choices":["fiction","fantasy","no n-fiction","legend"],"correct":2,"explanation":{"correct":"Answer: no n-fiction. Rule or clue: Reading comprehension means using details from the passage to understand ideas, events, and author choices. \"no n-fiction\" fits the genre clues in the prompt.","incorrect":[{"choice":"fiction","reason":"\"fiction\" is a different genre and does not match the clues given."},{"choice":"fantasy","reason":"\"fantasy\" is a different genre and does not match the clues given."},"",{"choice":"legend","reason":"\"legend\" is a different genre and does not match the clues given."}]},"studyAid":{"definition":"Reading comprehension means using details from the passage to understand ideas, events, and author choices.","example":"Find the sentence or detail that supports the answer before choosing.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sourceFile":"Proficient-1_reading.pdf","sourceQuestionNumber":3,"sourceCategory":"reading-test","sourceGrade":3,"sequence":181,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-book-genres-q0182","version":3,"contentHash":"sha256:40e0a13a86ed76d527a6eb95140ed9b11e5cdb28f1786eea5b62bfe38bbdaa8a","question":"Read the list. Setting Characters Problem Plot Resolution What literary device do theseelements describe?","choices":["story descriptions","genres","story structure","fiction"],"correct":2,"explanation":{"correct":"Answer: story structure. These elements together form the framework or sequence of events that organize a narrative, making 'story structure' the correct term for describing these parts.","incorrect":[{"choice":"story descriptions","category":"descriptive vs structural","reason":"While these elements are part of a story, 'story descriptions' refers to the details or imagery used to paint a picture, rather than the organizational framework of the narrative."},{"choice":"genres","category":"category vs component","reason":"Genres classify books by type (like mystery, science fiction, or fantasy). The listed terms are the building blocks of a plot, not the category of the book itself."},"",{"choice":"fiction","category":"category vs component","reason":"Fiction refers to stories that are imagined rather than factual. The list provided describes the specific architecture of a narrative, not the distinction between fact and fiction."}]},"studyAid":{"definition":"Story structure is the planned framework of a narrative that organizes characters, setting, and events into a clear beginning, middle, and end.","example":"Beginning (Introduction), Middle (Rising Action/Problem), End (Resolution/Conclusion).","strategyClue":"Ask yourself if the terms in the list describe what kind of book it is, or if they describe the specific parts used to build the story's timeline.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sourceFile":"Proficient-11_Informational Text.pdf","sourceQuestionNumber":10,"sourceCategory":"informational-text","sourceGrade":3,"sequence":182,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-book-genres-q0228","version":3,"contentHash":"sha256:903bdc2d212d1649c2aa6aad8ec1db70786c2011efd7c336cc413ac9e07b38bc","question":"Read the non-fiction passage. One difference between insects and all other ani mals is the number of legs they have. Only insects have six legs in the entire animal king dom. Adult insects have four wings and two antennae on their heads. If this is true, you can conclude that:","choices":["Spiders have wings; therefore, they are insects.","All animals are insects.","Insects are only found in North America.","A grasshopper is an insect."],"correct":3,"explanation":{"correct":"Answer: A grasshopper is an insect. Since the passage defines insects as having six legs, two antennae, and four wings, a grasshopper—which matches these biological characteristics—fits the definition provided in the text.","incorrect":[{"choice":"Spiders have wings; therefore, they are insects.","category":"factual contradiction","reason":"The passage states that all insects have six legs. Spiders have eight legs, so they do not fit the rule provided in the text."},{"choice":"All animals are insects.","category":"overgeneralization error","reason":"The text explains that insects are a specific group among other animals, not that every animal is an insect."},{"choice":"Insects are only found in North America.","category":"unsupported information","reason":"The passage discusses the physical body parts of insects, but it mentions nothing about their geographic location or where they are found."},""]},"studyAid":{"definition":"A conclusion is a logical decision based on the evidence and facts provided in a text.","example":"If the text says 'All dogs bark,' and you see a creature that is a dog, you can conclude it will bark.","strategyClue":"Look at the specific traits listed in the passage (legs, wings, antennae). Compare these requirements to each choice to see which one logically fits all the rules.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sourceFile":"Proficient-9_Informational Text.pdf","sourceQuestionNumber":8,"sourceCategory":"informational-text","sourceGrade":3,"sequence":228,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-book-genres-q0263","version":3,"contentHash":"sha256:c6ef56fb374de1b9e14e248b8fca02a91d7e955bc69d0fbf8871b86a1540d669","question":"What kind of writing is this? Dear Jill, I went to the zoo with my mother. I like to see the animals! Can you come to the zoo with me on Saturday? Your friend, Jack","choices":["friendly letter","tell a story","tell facts","formal letter"],"correct":0,"explanation":{"correct":"Answer: friendly letter. This writing includes a greeting (Dear Jill), a personal message about the writer's day, and a closing (Your friend, Jack), which are the essential parts of a friendly letter.","incorrect":["",{"choice":"tell a story","category":"purpose of writing","reason":"While the writer mentions going to the zoo, the main purpose of this writing is to communicate with a friend and invite them to do something, not just to describe a sequence of events."},{"choice":"tell facts","category":"informative writing","reason":"Telling facts is for informational reports. This piece uses personal feelings and conversational language, like 'I like to see,' which is characteristic of personal communication, not an informative report."},{"choice":"formal letter","category":"letter style","reason":"Formal letters are used for business or professional requests and have a very serious tone. 'Your friend' is an informal closing used specifically in letters to people you know well."}]},"studyAid":{"definition":"A friendly letter is a way to communicate with someone you know, featuring a greeting, a body, and a personal closing.","example":"Friendly letter: Dear Sam, how are you? / Formal letter: Dear Mr. Smith, I am writing to apply for the position.","strategyClue":"Look for a greeting and a closing signature. Then, ask yourself if the tone sounds like someone talking to a classmate or a teacher/stranger.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["literature","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sourceFile":"Basic-1_Literature.pdf","sourceQuestionNumber":3,"sourceCategory":"literature","sourceGrade":3,"sequence":263,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-book-genres-q0267","version":3,"contentHash":"sha256:dd4dca4ca5e7c8d1a803e9593c2474b0d821699169ac081f2f058dfe364b8df3","question":"Read the passage. Bats are nocturnal animals. Bats come in many sizes and shapes. Bats hunt for food at night. Bats usually live in caves. What kind of writing is this?","choices":["poetry","fairy tale","non-fiction","fiction"],"correct":2,"explanation":{"correct":"Answer: non-fiction. This passage provides factual information about the habits and characteristics of real animals, which is the definition of non-fiction writing.","incorrect":[{"choice":"poetry","category":"incorrect text structure","reason":"Poetry often uses line breaks, stanzas, and rhythm to express feelings. This passage uses complete sentences in paragraphs to share facts."},{"choice":"fairy tale","category":"genre error","reason":"Fairy tales involve magic, make-believe characters, and imaginary events. Since bats are real animals and the information is factual, it is not a fairy tale."},"",{"choice":"fiction","category":"genre error","reason":"Fiction writing is invented by the author. Because this passage describes real-world scientific observations about bats, it is not an invented story."}]},"studyAid":{"definition":"Non-fiction is writing that is based on facts, real events, and real people, intended to inform or teach the reader about the world.","example":"A biography of a scientist, a textbook about the solar system, a book about how to bake cookies.","strategyClue":"Ask yourself: 'Is the information in this passage true and could it be proven by a scientist?' If the answer is yes, it is likely non-fiction.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["literature","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sourceFile":"Basic-1_Literature.pdf","sourceQuestionNumber":7,"sourceCategory":"literature","sourceGrade":3,"sequence":267,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-book-genres-q0268","version":3,"contentHash":"sha256:6b881d9fdf546912cf9a269acc1d6c77be0c95db8629a95e6e89cf0419b92985","question":"Read the following Mary had a little lamb. Whose fleece was white as snow, And Everywhere that Mary went, The lamb was sure to go. What kind of writing is this?","choices":["poetry","non-fiction","fiction","fairy tale"],"correct":0,"explanation":{"correct":"Answer: poetry. This writing uses a regular rhythm, rhyming sounds like 'snow' and 'go', and is organized into lines, which are the main characteristics of a poem.","incorrect":["",{"choice":"non-fiction","category":"factual writing style","reason":"Non-fiction is writing that tells facts about the real world. While Mary might have been a real person, the song-like rhythm and rhyme scheme identify this as poetry."},{"choice":"fiction","category":"narrative prose style","reason":"Fiction usually refers to stories told in paragraphs and sentences, often called prose. Because this has verses and rhythm, it is a specific type of creative writing called poetry."},{"choice":"fairy tale","category":"story genre","reason":"A fairy tale is a type of story often involving magic or make-believe characters. This text is a nursery rhyme, which falls under the category of poetry due to its structure."}]},"studyAid":{"definition":"Poetry is a type of writing that uses rhythm, rhyme, and line breaks to express ideas and feelings rather than just telling a story in sentences.","example":"Poetry: 'Roses are red, violets are blue.' Prose: 'The roses in the garden are red and the violets are blue.'","strategyClue":"Look at the visual layout and the sound of the words. If the words are broken into short lines and have a beat or rhyme when read aloud, classify it by its structure rather than just its subject matter.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["literature","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sourceFile":"Basic-1_Literature.pdf","sourceQuestionNumber":8,"sourceCategory":"literature","sourceGrade":3,"sequence":268,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-book-genres-q0272","version":3,"contentHash":"sha256:3f44b467f437bbe2d6e3efb6b044a60ab5ff2b8453656ee70be81261213f6ae4","question":"Read the sentences: 1. Gorillas are plant-eating creatures. 2. Gorillas can be found in Africa. 3. All gorillas are ugly, scary and mean. 4. Scientists think gorillas could have been as tall as ten feet. Which of the above sentences are non-fiction?","choices":["2 and 3","1 and 2","1, 2, and 4","None of the above"],"correct":2,"explanation":{"correct":"Answer: 1, 2, and 4. Non-fiction writing is based on facts and reality. Sentences 1, 2, and 4 provide information about diet, location, and scientific theories, while sentence 3 expresses a subjective opinion rather than a factual statement.","incorrect":[{"choice":"2 and 3","category":"opinion vs fact","reason":"Sentence 3 is an opinion about how gorillas look or act, which is subjective. Non-fiction content relies on objective facts, not personal judgments."},{"choice":"1 and 2","category":"missing factual evidence","reason":"You missed sentence 4, which reports on scientific research findings. Theories and studies about animal history are common topics in non-fiction texts."},"",{"choice":"None of the above","category":"misidentifying informational text","reason":"Several of these sentences contain verifiable information. Non-fiction is simply writing that describes real-world events, creatures, or science."}]},"studyAid":{"definition":"Non-fiction is writing that is based on facts, real events, and actual people or animals, rather than imagination or personal opinion.","example":"Fact: Gorillas live in forests (non-fiction). Opinion: Gorillas are grumpy (not non-fiction).","strategyClue":"Ask yourself if the statement can be proven true by a researcher or scientist. If a sentence expresses a feeling or a personal judgment that others might disagree with, it is likely not a factual non-fiction statement.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["literature","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-book-genres","sourceFile":"Proficient-1_Literature.pdf","sourceQuestionNumber":2,"sourceCategory":"literature","sourceGrade":3,"sequence":272,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, with 15 exact-match questions for every supported grade and difficulty"}};
  const bank = window.QUESTION_BANK = window.QUESTION_BANK || {};
  const existing = bank["reading-comprehension-book-genres"];
  if (existing && Array.isArray(existing.questions)) {
    const seen = new Set(existing.questions.map(question => question && question.id));
    chunkSet.questions.forEach(question => {
      if (!seen.has(question && question.id)) existing.questions.push(question);
    });
  } else {
    bank["reading-comprehension-book-genres"] = chunkSet;
  }
})();
